    for rank, item in enumerate(ordered, start=1):
        evidence_sources.append({
            "record_id": item.get("record_id", ""),
            "source_id": item.get("source_id", ""),
            "source_weight": item.get("source_weight", 0),
            "rank": rank,
        })
    return pd.DataFrame(evidence_sources)


