        recommendation = {"top_need": "", "decision": "maintain"}
    else:
        top_record = retained_df.iloc[0].to_dict()
        recommendation = {
            "top_need": top_record.get("need", ""),
            "decision": "prioritize" if top_record.get("unsupported", False) else "maintain",
        }
