        "job_id": "downstream_priority_recommendation",
        "coverage_count": int(len(coverage_df)),
        "priority_count": int(len(retained_priorities_df)),
    },
}
sys.stdout.write(json.dumps(result, sort_keys=True, separators=(",", ":")))

